import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import 'package:intl/intl.dart';

const cream = Color(0xFFFAF9F6);
const forest = Color(0xFF174B2A);
const categoryColors = <String, Color>{
  '교회': Color(0xFF8DBB8B), '개발': Color(0xFF78B5EE),
  '학업': Color(0xFFF2D17C), '디자인': Color(0xFFB99AE8),
  '영상': Color(0xFF83D0C6), '개인': Color(0xFFB9BEC4),
};

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  const url = String.fromEnvironment('SUPABASE_URL');
  const key = String.fromEnvironment('SUPABASE_ANON_KEY');
  if (url.isEmpty || key.isEmpty) {
    runApp(const SetupApp());
    return;
  }
  await Supabase.initialize(url: url, anonKey: key);
  runApp(const ObservatoryApp());
}

class SetupApp extends StatelessWidget {
  const SetupApp({super.key});
  @override Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false, theme: appTheme,
    home: const Scaffold(body: Center(child: Padding(padding: EdgeInsets.all(32), child: Text('Supabase 설정이 필요해.\nREADME의 실행 방법을 따라 SUPABASE_URL과 SUPABASE_ANON_KEY를 전달해 줘.', textAlign: TextAlign.center)))),
  );
}

final appTheme = ThemeData(
  useMaterial3: true, scaffoldBackgroundColor: cream, colorScheme: ColorScheme.fromSeed(seedColor: forest, surface: cream),
  fontFamily: 'Arial', cardTheme: const CardThemeData(color: Colors.white, elevation: 0, margin: EdgeInsets.zero),
  inputDecorationTheme: InputDecorationTheme(filled: true, fillColor: const Color(0xFFF5F6F2), border: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide.none)),
);

class ObservatoryApp extends StatelessWidget {
  const ObservatoryApp({super.key});
  @override Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner: false, title: 'Observatory', theme: appTheme, home: const AuthGate());
}

class AuthGate extends StatelessWidget {
  const AuthGate({super.key});
  @override Widget build(BuildContext context) => StreamBuilder<AuthState>(
    stream: Supabase.instance.client.auth.onAuthStateChange,
    builder: (context, snap) => Supabase.instance.client.auth.currentSession == null ? const LoginPage() : const MainShell(),
  );
}

class LoginPage extends StatefulWidget { const LoginPage({super.key}); @override State<LoginPage> createState()=>_LoginPageState(); }
class _LoginPageState extends State<LoginPage> {
  final email=TextEditingController(), password=TextEditingController(); bool signup=false, busy=false; String? error;
  Future<void> submit() async { setState(()=>busy=true); try { if(signup){ await Supabase.instance.client.auth.signUp(email:email.text.trim(),password:password.text); } else { await Supabase.instance.client.auth.signInWithPassword(email:email.text.trim(),password:password.text); } } catch(e){ setState(()=>error=e.toString()); } finally { if(mounted)setState(()=>busy=false); } }
  @override Widget build(BuildContext context)=>Scaffold(body: Center(child: ConstrainedBox(constraints: const BoxConstraints(maxWidth:380),child: Padding(padding:const EdgeInsets.all(28),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.all_inclusive,color:forest,size:42),const SizedBox(height:12),const Text('Observatory',textAlign:TextAlign.center,style:TextStyle(fontSize:28,fontWeight:FontWeight.bold,color:forest)),const SizedBox(height:28),Text(signup?'계정 만들기':'로그인',style:const TextStyle(fontSize:20,fontWeight:FontWeight.w700)),const SizedBox(height:14),TextField(controller:email,decoration:const InputDecoration(labelText:'이메일')),const SizedBox(height:10),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'비밀번호')),if(error!=null) Padding(padding:const EdgeInsets.only(top:10),child:Text(error!,style:const TextStyle(color:Colors.red))),const SizedBox(height:16),FilledButton(onPressed:busy?null:submit,child:Text(busy?'잠시만…':signup?'가입하기':'로그인')),TextButton(onPressed:()=>setState(()=>signup=!signup),child:Text(signup?'이미 계정이 있어':'처음 사용하는 경우 계정 만들기'))])))));
}

class MainShell extends StatefulWidget { const MainShell({super.key}); @override State<MainShell> createState()=>_MainShellState(); }
class _MainShellState extends State<MainShell> {
  int page=0; String? categoryId; String? categoryName;
  void openCategory(Map<String,dynamic> c){setState(()=>{categoryId=c['id'].toString(),categoryName=c['name'].toString(),page=1});}
  @override Widget build(BuildContext context){
    final wide=MediaQuery.sizeOf(context).width>=850;
    final pages=[HomePage(onCategory:openCategory),CategoryPage(categoryId:categoryId,categoryName:categoryName),const ProjectsPage(),const TasksPage(),const SchedulePage(),const ArchivePage()];
    final body=pages[page];
    return Scaffold(body:Row(children:[if(wide) _Sidebar(page:page,onSelect:(v)=>setState(()=>page=v),onCategory:openCategory),Expanded(child:body)]),bottomNavigationBar:wide?null:NavigationBar(selectedIndex:page>4?0:page,onDestinationSelected:(v)=>setState(()=>page=v),destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),label:'Home'),NavigationDestination(icon:Icon(Icons.folder_outlined),label:'Categories'),NavigationDestination(icon:Icon(Icons.layers_outlined),label:'Projects'),NavigationDestination(icon:Icon(Icons.check_box_outlined),label:'Tasks'),NavigationDestination(icon:Icon(Icons.calendar_month_outlined),label:'Schedule') ]));
  }
}

class _Sidebar extends StatelessWidget {
 final int page; final ValueChanged<int> onSelect; final ValueChanged<Map<String,dynamic>> onCategory;
 const _Sidebar({required this.page,required this.onSelect,required this.onCategory});
 @override Widget build(BuildContext context)=>Container(width:238,color:Colors.white,padding:const EdgeInsets.fromLTRB(22,28,18,18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Row(children:[Icon(Icons.all_inclusive,color:forest,size:28),SizedBox(width:9),Text('Observatory',style:TextStyle(color:forest,fontWeight:FontWeight.w800,fontSize:20))]),const SizedBox(height:34),..._navItems(),const Padding(padding:EdgeInsets.symmetric(vertical:18),child:Divider(color:Color(0xFFECEFE9))),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('CATEGORIES',style:TextStyle(fontSize:11,fontWeight:FontWeight.bold,color:forest)),IconButton(onPressed:()=>_categoryDialog(context),icon:const Icon(Icons.add,color:forest))]),Expanded(child:FutureBuilder<List<Map<String,dynamic>>>(future:db.from('categories').select().order('name'),builder:(c,s)=>ListView(children:(s.data??[]).map((x)=>ListTile(dense:true,contentPadding:const EdgeInsets.symmetric(horizontal:8),leading:CircleAvatar(radius:6,backgroundColor:Color(int.parse(x['color'].toString()))),title:Text(x['name']),onTap:()=>onCategory(x))).toList()))),TextButton.icon(onPressed:()=>Supabase.instance.client.auth.signOut(),icon:const Icon(Icons.logout,size:16),label:const Text('로그아웃'))]));
 List<Widget> _navItems()=>[
  _nav('Home',Icons.home_outlined,0),_nav('Categories',Icons.folder_outlined,1),_nav('Projects',Icons.layers_outlined,2),_nav('Tasks',Icons.check_box_outlined,3),_nav('Calendar',Icons.calendar_month_outlined,4),_nav('Archive',Icons.inventory_2_outlined,5)];
 Widget _nav(String t,IconData i,int n)=>Padding(padding:const EdgeInsets.only(bottom:4),child:ListTile(selected:page==n,selectedTileColor:const Color(0xFFEDF4EA),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(12)),leading:Icon(i,color:forest),title:Text(t,style:const TextStyle(fontWeight:FontWeight.w600)),onTap:()=>onSelect(n)));
}

final db=Supabase.instance.client;
String dateLabel(dynamic v)=>v==null?'날짜 미정':DateFormat('MM.dd').format(DateTime.parse(v.toString()));
Color catColor(dynamic v){ final raw=(v??'0xFF83D0C6').toString().replaceFirst('0x',''); return Color(int.tryParse(raw,radix:16)??0xFF83D0C6); }

