 @override Widget build(BuildContext context)=>_PageFrame(title:'Projects',action:TextButton(onPressed:()=>_projectDialog(context),child:const Text('+ New Project')),child:FutureBuilder<List<dynamic>>(future:Future.wait([db.from('projects').select('*,categories(name,color)').eq('archived',false).order('due_date'),db.from('tasks').select('*,categories(name,color)').eq('status','todo').order('due_date').limit(6),db.from('events').select('*,categories(name,color)').gte('starts_at',DateTime.now().toIso8601String()).order('starts_at').limit(5)]),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final projects=s.data![0] as List, tasks=s.data![1] as List, events=s.data![2] as List;return ListView(padding:const EdgeInsets.all(26),children:[Wrap(spacing:14,runSpacing:14,children:projects.take(8).map((p)=>SizedBox(width:220,child:_ProjectCard(p:p))).toList()),const SizedBox(height:28),LayoutBuilder(builder:(c,box)=>Wrap(spacing:20,runSpacing:20,children:[SizedBox(width:box.maxWidth>900?(box.maxWidth-20)/2:box.maxWidth,child:_Panel(title:'Tasks',child:Column(children:tasks.map((t)=>_TaskRow(t:t)).toList()))),SizedBox(width:box.maxWidth>900?(box.maxWidth-20)/2:box.maxWidth,child:_Panel(title:'Schedule',child:Column(children:events.map((e)=>_EventRow(e:e)).toList()))) ]))]);}));
