Future<void> _categoryDialog(BuildContext context)async{final name=TextEditingController();String color='0xFF83D0C6';await showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('New Category'),content:TextField(controller:name,decoration:const InputDecoration(labelText:'Category name')),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:()async{await db.from('categories').insert({'user_id':db.auth.currentUser!.id,'name':name.text.trim(),'color':color});if(context.mounted)Navigator.pop(context);},child:const Text('Create'))]));}
Future<List<Map<String,dynamic>>> _categories()async=>db.from('categories').select().order('name');
Future<void> _projectDialog(BuildContext context,{String? categoryId})async{final name=TextEditingController(),desc=TextEditingController();String? cat=categoryId;DateTime? due;final cats=await _categories();if(context.mounted)await showDialog(context:context,builder:(_)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('New Project'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Project name')),TextField(controller:desc,decoration:const InputDecoration(labelText:'Description')),DropdownButtonFormField<String>(value:cat,decoration:const InputDecoration(labelText:'Category'),items:cats.map((x)=>DropdownMenuItem(value:x['id'].toString(),child:Text(x['name']))).toList(),onChanged:(v)=>set(()=>cat=v)),TextButton(onPressed:()async{final d=await showDatePicker(context:c,firstDate:DateTime(2020),lastDate:DateTime(2035),initialDate:DateTime.now());if(d!=null)set(()=>due=d);},child:Text(due==null?'Set due date':DateFormat('yyyy-MM-dd').format(due!)))])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:()async{if(name.text.trim().isEmpty||cat==null)return;await db.from('projects').insert({'user_id':db.auth.currentUser!.id,'name':name.text.trim(),'description':desc.text,'category_id':cat,'due_date':due?.toIso8601String().split('T').first,'progress':0});if(c.mounted)Navigator.pop(c);},child:const Text('Create'))])));}
